<script lang="ts">
 import {onMount} from 'svelte'; import {dialogFocus} from './lib/dialog'; import {categoriesGrouped, today, parseAmount, createSchedule, type AccountOverview, type CategoryGroup} from './lib/api';
 let {accounts, close, saved}:{accounts:AccountOverview[]; close:()=>void; saved:()=>void}=$props();
 let name=$state(''), expense=$state(true), amount=$state(''), account=$state(''), payee=$state(''), category=$state(''), frequency=$state('monthly'), interval=$state(1), start=$state(''), skip=$state(false), auto=$state(false), groups=$state<CategoryGroup[]>([]), error=$state(''), saving=$state(false);
 onMount(() => {account=String(accounts[0]?.id ?? ''); void Promise.all([today(),categoriesGrouped()]).then(([d,g])=>{start=d;groups=g;}).catch(e=>error=String(e));});
 async function save(){if(saving)return;saving=true;try{const cents=await parseAmount(amount);if(cents===null||!name.trim()||!account||!start){error='Completa los datos del pago';saving=false;return;}await createSchedule({name,amount:expense?-cents:cents,autoPost:auto,accountId:Number(account),categoryId:category?Number(category):null,payee,recurrence:{start,frequency,interval,skipWeekend:skip,weekendMode:'after'}});saved();}catch(e){error=String(e);saving=false;}}
 function keys(e:KeyboardEvent){if(e.key==='Escape'){e.preventDefault();close();}}
</script>
<div class="backdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="schedule-title" tabindex="-1" use:dialogFocus onkeydown={keys}><h2 id="schedule-title">Nuevo pago programado</h2><p>Organiza los pagos que se repiten</p><form onsubmit={e=>{e.preventDefault();void save();}}>
<label>Nombre<input bind:value={name} required/></label><fieldset><legend>Tipo</legend><label><input type="radio" bind:group={expense} value={true}/> Gasto</label><label><input type="radio" bind:group={expense} value={false}/> Ingreso</label></fieldset><label>Monto<input bind:value={amount} inputmode="decimal" required/></label><label>Cuenta<select bind:value={account} required><option value="">Selecciona una cuenta</option>{#each accounts as a}<option value={String(a.id)}>{a.name}</option>{/each}</select></label><label>Comercio<input bind:value={payee}/></label><label>Categoría<select bind:value={category}><option value="">Sin categoría</option>{#each groups as g}<optgroup label={g.name}>{#each g.categories.filter(c=>!c.hidden) as c}<option value={String(c.id)}>{c.name}</option>{/each}</optgroup>{/each}</select></label>
<label>Repetición<select bind:value={frequency}><option value="daily">Diario</option><option value="weekly">Semanal</option><option value="monthly">Mensual</option><option value="yearly">Anual</option></select></label><label>Cada {interval}<input type="number" min="1" max="52" bind:value={interval}/></label><label>Primera fecha<input type="date" bind:value={start} required/></label><label class="check"><input type="checkbox" bind:checked={skip}/> Si cae en fin de semana, pasar al lunes</label><label class="check"><input type="checkbox" bind:checked={auto}/> Registrar automáticamente</label><p>Los pagos automáticos se registran al abrir la app y cada hora, sin confirmación adicional.</p>{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="buttons"><button type="button" onclick={close}>Cancelar</button><button type="submit" disabled={saving}>Guardar</button></div></form></div></div>
<style>.backdrop{position:fixed;inset:0;background:#0009;display:grid;place-items:center;z-index:10;padding:16px}.modal{background:var(--card);border:1px solid var(--border);border-radius:18px;padding:24px;width:min(520px,100%);max-height:95vh;overflow:auto}h2,p{margin:0 0 12px}p{color:var(--muted)}form{display:grid;gap:10px}label:not(.check){display:grid;gap:4px}input,select,button{font:inherit;color:inherit;background:var(--canvas);border:1px solid var(--border);border-radius:8px;padding:8px}fieldset{display:flex;gap:12px;border:0;padding:0}fieldset label{display:flex!important}.buttons{display:flex;justify-content:flex-end;gap:8px}button{cursor:pointer}.error{color:var(--coral)}</style>
